(()=>{
 const route='#verhandlungspoker';
 function integrate(){
  const nav=document.getElementById('nav'),main=document.getElementById('main');if(!nav||!main)return;
  if(!document.getElementById('pokerNav')){const a=document.createElement('a');a.id='pokerNav';a.href=route;a.textContent='▶ Verhandlungspoker';a.style.cssText='background:#dfef78;color:#102631;font-weight:750;margin:12px 0;border-radius:6px;padding:14px';nav.prepend(a);}
  const active=location.hash===route,link=document.getElementById('pokerNav');link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');
  if(active){if(document.getElementById('integratedPoker'))return;document.title='Verhandlungspoker · TERROR';main.innerHTML='<p class="breadcrumb"><a href="#spiele">Lernspiele</a> / Verhandlungspoker</p><h1>Verhandlungspoker: Terror</h1><p>Sechs Rollen. Dreizehn Lagefenster. Karten, begründete Abstimmungen, Vetos und politische Verantwortung. Das vollständige Spiel läuft hier innerhalb der Lernplattform.</p><p><a class="button" href="verhandlungspoker/">Spiel in voller Breite starten →</a> · <a href="#befehlskette">Befehlskette nachschlagen</a></p><iframe id="integratedPoker" title="Verhandlungspoker: Terror – vollständiges Rollenspiel" src="verhandlungspoker/" style="width:100%;height:85vh;min-height:650px;border:1px solid #bdc9ca;border-radius:10px" allow="fullscreen"></iframe>';return;}
  for(const a of main.querySelectorAll('a[href="https://patrickfischerksa.github.io/verhandlungspoker-terror/"]')){a.href=route;a.removeAttribute('target');a.textContent='Verhandlungspoker hier spielen →';}
  if(['#spiele','#simulation','#start','#lektuere/urteile'].includes(location.hash)&&!document.getElementById('pokerEntry')){const card=document.createElement('section');card.id='pokerEntry';card.className='section card';card.style.cssText='border-left:6px solid #91a52e;background:#f3f7df;margin:24px 0';card.innerHTML='<span class="eyebrow">DIREKT SPIELEN · SECHS ROLLEN</span><h2>Verhandlungspoker: Wer trägt die Verantwortung?</h2><p>Spielt alle dreizehn Lagefenster: Rollen und Karten, Abstimmungsgewichte und Vetos, Verantwortungsmatrix und Endauswertung. Gemeinsam am Bildschirm oder mit Rollenpaketen auf dem Handy.</p><a class="button" href="#verhandlungspoker">Verhandlungspoker starten →</a>';const heading=main.querySelector('h1');if(heading?.parentElement!==main&&heading?.parentElement)heading.parentElement.after(card);else if(heading)heading.after(card);else main.prepend(card);}
 }
 new MutationObserver(integrate).observe(document.getElementById('main'),{childList:true});window.addEventListener('hashchange',integrate);integrate();
})();
